insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e1-u1', (select id from public.learn_courses where code = 'english-e1'), '알파벳, 인사, 숫자와 색깔, 가족, 교실', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e1-l1', (select id from public.learn_units where code = 'english-e1-u1'), '알파벳과 첫소리', '낱말은 첫소리와 첫 글자를 알면 쉽게 기억돼요. 소리를 내며 따라 읽어 보세요.', 'ball → B, cat → C, dog → D', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e1-l1'), (select id from public.learn_skills where code = 'e.e1.alpha') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e1-l2', (select id from public.learn_units where code = 'english-e1-u1'), '인사말', '만났을 때는 **Hello**, 헤어질 때는 **Goodbye**라고 해요. 이름은 **My name is ...**로 말해요.', 'Hello! My name is Mina.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e1-l2'), (select id from public.learn_skills where code = 'e.e1.greet') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e1-l3', (select id from public.learn_units where code = 'english-e1-u1'), '숫자와 색깔', 'one, two, three... 숫자와 red, blue, yellow... 색깔 낱말을 익혀요.', 'three = 3, red = 빨강', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e1-l3'), (select id from public.learn_skills where code = 'e.e1.numcol') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e1-l4', (select id from public.learn_units where code = 'english-e1-u1'), '가족', 'mother(엄마), father(아빠), grandmother(할머니), baby(아기)처럼 가족을 부르는 낱말이에요.', 'This is my mother.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e1-l4'), (select id from public.learn_skills where code = 'e.e1.family') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e1-l5', (select id from public.learn_units where code = 'english-e1-u1'), '교실 낱말', 'desk, chair, bag, pencil, book... 교실에서 쓰는 낱말을 영어로 말해 보세요.', 'I have a pencil.', 4, 'PUBLISHED') on conflict (code) do nothing;
