insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e4-u1', (select id from public.learn_courses where code = 'english-e4'), '시제, 질문과 부정, 꾸미는 말, 위치, 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e4-l1', (select id from public.learn_units where code = 'english-e4-u1'), '현재·과거·미래', '지금·반복은 **현재형**, 지난 일은 **-ed**, 앞으로 할 일은 **will + 동사원형**으로 말해요.', 'I will visit my aunt tomorrow.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e4-l1'), (select id from public.learn_skills where code = 'e.e4.tense') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e4-l2', (select id from public.learn_units where code = 'english-e4-u1'), '의문문과 부정문', '묻는 말은 **Do/Does**로 시작하고, 아니라고 말할 때는 **don''t/doesn''t**를 써요.', 'Do you like pizza? I don''t like onions.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e4-l2'), (select id from public.learn_skills where code = 'e.e4.qneg') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e4-l3', (select id from public.learn_units where code = 'english-e4-u1'), '모양과 느낌을 나타내는 말', 'big(큰), small(작은), hot(뜨거운), cold(차가운)처럼 모습이나 느낌을 설명하는 말이에요.', 'The ice cream is cold.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e4-l3'), (select id from public.learn_skills where code = 'e.e4.adj') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e4-l4', (select id from public.learn_units where code = 'english-e4-u1'), '장소를 나타내는 말', '**on**(위에), **in**(안에), **under**(아래에), **behind**(뒤에)로 물건의 위치를 말해요.', 'The book is on the desk.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e4-l4'), (select id from public.learn_skills where code = 'e.e4.prep') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e4-l5', (select id from public.learn_units where code = 'english-e4-u1'), '짧은 글 읽기', '누가, 어디서, 무엇을 했는지 글에서 찾아 답해요.', 'Mina goes to the park.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e4-l5'), (select id from public.learn_skills where code = 'e.e4.read') on conflict do nothing;
