insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e5-u1', (select id from public.learn_courses where code = 'english-e5'), '관사와 복수형, 비교, 미래, 문장 바꿔 쓰기, 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l1', (select id from public.learn_units where code = 'english-e5-u1'), '관사·복수형·There is/are', '모음 소리 앞에는 **an**, 자음 소리 앞에는 **a**를 써요. 하나면 **There is**, 여러 개면 **There are**를 써요.', 'an apple, two boxes, There are three books.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l1'), (select id from public.learn_skills where code = 'e.e5.gram') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l2', (select id from public.learn_units where code = 'english-e5-u1'), '비교하는 말', '둘을 비교할 때는 **-er + than**, 가장 ~한 것은 **the -est**를 써요. 긴 낱말은 **more**를 써요.', 'Tom is taller than Ben.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l2'), (select id from public.learn_skills where code = 'e.e5.comp') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l3', (select id from public.learn_units where code = 'english-e5-u1'), '미래 표현', '앞으로 할 일은 **will + 동사원형** 또는 **be going to + 동사원형**으로 말해요.', 'I am going to visit Jeju.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l3'), (select id from public.learn_skills where code = 'e.e5.future') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l4', (select id from public.learn_units where code = 'english-e5-u1'), '문장 바꿔 쓰기', '부정문은 **not / don''t / doesn''t / didn''t**를, 의문문은 **Are / Do / Does**를 문장 앞에 써요.', 'I am happy. → I am not happy.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l4'), (select id from public.learn_skills where code = 'e.e5.transform') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l5', (select id from public.learn_units where code = 'english-e5-u1'), '글 이해하기', '긴 글은 누가·어디·언제·무엇을에 밑줄을 치듯 찾아 읽으면 쉬워요.', 'Ken lives in Busan.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l5'), (select id from public.learn_skills where code = 'e.e5.read') on conflict do nothing;
