insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e6-u1', (select id from public.learn_courses where code = 'english-e6'), '시제 총정리, 조동사, 낱말, 이어 주는 말, 문단 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l1', (select id from public.learn_units where code = 'english-e6-u1'), '시제 총정리', '지금 하는 일은 **be + -ing**, 지난 일은 **과거형**, 앞으로 할 일은 **will / be going to**로 말해요.', 'The baby is sleeping now.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l1'), (select id from public.learn_skills where code = 'e.e6.tense') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l2', (select id from public.learn_units where code = 'english-e6-u1'), 'can, must, should, may', '**can**(할 수 있다), **must**(해야 한다), **should**(하는 게 좋다), **may**(해도 된다) 다음에는 동사원형이 와요.', 'You should brush your teeth.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l2'), (select id from public.learn_skills where code = 'e.e6.modal') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l3', (select id from public.learn_units where code = 'english-e6-u1'), '낱말 넓히기', '비슷한 뜻의 낱말과 반대말을 함께 익히면 낱말이 두 배로 늘어요.', 'big ≈ large, happy ↔ sad', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l3'), (select id from public.learn_skills where code = 'e.e6.vocab') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l4', (select id from public.learn_units where code = 'english-e6-u1'), '이어 주는 말', '**because**(이유), **so**(결과), **but**(반대), **if**(만약), **when**(~할 때)으로 문장을 이어요.', 'I was tired, so I went to bed early.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l4'), (select id from public.learn_skills where code = 'e.e6.clause') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l5', (select id from public.learn_units where code = 'english-e6-u1'), '문단 읽기', '여러 문장으로 된 글을 읽고 누가·언제·왜 했는지 찾아 답해요.', 'Jina was tired because they walked a lot.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l5'), (select id from public.learn_skills where code = 'e.e6.read') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('en-m1-unit1', (select id from public.learn_courses where code = 'en-m1-basics'), '단어와 기초 문법', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l1', (select id from public.learn_units where code = 'en-m1-unit1'), '일상 단어 익히기', '자주 쓰는 단어는 **소리 + 뜻 + 쓰기**를 함께 익히면 오래 기억돼요. 스피커 버튼으로 발음을 들어 보세요.', 'library = 도서관 / desk = 책상 / milk = 우유', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l1'), (select id from public.learn_skills where code = 'e.vocab') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l2', (select id from public.learn_units where code = 'en-m1-unit1'), 'be동사 am / are / is', 'be동사는 주어에 따라 모양이 달라져요. **I → am**, **he / she / it → is**, **you / we / they → are**.', 'I am a student. She is my friend. They are in the classroom.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l2'), (select id from public.learn_skills where code = 'e.be') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l3', (select id from public.learn_units where code = 'en-m1-unit1'), '일반동사 현재형', '주어가 **he / she / it(3인칭 단수)** 이면 동사에 **-s / -es**를 붙여요. -ch, -sh, -s, -x, -o 로 끝나면 -es, 자음+y는 y를 i로 바꾸고 -es!', 'go → goes / watch → watches / study → studies', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l3'), (select id from public.learn_skills where code = 'e.pres') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l4', (select id from public.learn_units where code = 'en-m1-unit1'), '복수형과 문장 만들기', '명사가 둘 이상이면 보통 **-s**를 붙이고, -x로 끝나면 **-es**, 불규칙 복수형은 따로 외워요. 문장은 **주어 → 동사 → 나머지** 순서예요.', 'book → books / box → boxes / child → children', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l4'), (select id from public.learn_skills where code = 'e.plural') on conflict do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l4'), (select id from public.learn_skills where code = 'e.order') on conflict do nothing;
